-- PT106-S1-Q14. Batch 11.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch11$PT106-S1-Q14$batch11$ AND q.stimulus=$batch11$The axis of Earth’s daily rotation is tilted with respect to the plane of its orbit at an angle of roughly 23 degrees. That angle can be kept fairly stable only by the gravitational influence of Earth’s large, nearby Moon. Without such a stable and moderate axis tilt, a planet’s climate is too extreme and unstable to support life. Mars, for example, has only very small moons, tilts at wildly fluctuating angles, and cannot support life.$batch11$ AND q.prompt=$batch11$If the statements above are true, which one of the following must also be true on the basis of them?$batch11$ AND q.correct_choice=$batch11$B$batch11$) THEN RAISE EXCEPTION 'Question changed: PT106-S1-Q14'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch11$PT106-S1-Q14$batch11$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT106-S1-Q14'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch11$PT106-S1-Q14$batch11$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch11$Statements$batch11$, $batch11$Earth's tilt can stay stable only because of the Moon's gravity. Without a stable, moderate tilt, a planet's climate can't support life. Mars has small moons, a wild tilt, and no life.$batch11$), (1, $batch11$Evaluate$batch11$, $batch11$Chain the requirements. Support life → stable tilt. For Earth, stable tilt → the Moon. So Earth supporting life → the Moon. Take the contrapositive: no Moon → no stable tilt → no life.$batch11$), (2, $batch11$Goal$batch11$, $batch11$If Earth lost its Moon, Earth's climate couldn't support life.$batch11$)) v(position,label,body) WHERE q.qid=$batch11$PT106-S1-Q14$batch11$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch11$A$batch11$, $batch11$A large moon is required for a stable tilt, and a stable tilt is required for life. Neither is enough. Mars might still fail for other reasons.$batch11$), ($batch11$B$batch11$, $batch11$Without the Moon, Earth's tilt can't stay stable, and without a stable tilt, the climate can't support life.$batch11$), ($batch11$C$batch11$, $batch11$A stable tilt is required for life, not enough for it.$batch11$), ($batch11$D$batch11$, $batch11$The passage names the Moon as the stabilizer. It never says other forces have little effect on the tilt.$batch11$), ($batch11$E$batch11$, $batch11$The number of moons never matters. Size and closeness do.$batch11$)) v(letter,body) WHERE q.qid=$batch11$PT106-S1-Q14$batch11$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
COMMIT;
